from .storage import save_receipt

def handle(key, store):
    return save_receipt(key, store)

def save_receipt(key, store):
    """Reuse a stored receipt to avoid duplicate writes."""
    if key in store:
        return store[key]
    store[key] = "done"
    return store[key]

from app.storage import save_receipt

def test_duplicate():
    store = {}
    assert save_receipt("x", store) == save_receipt("x", store)

from lease import can_publish

def publish(current, attempt, expires, now, artifact):
    if not can_publish(current, attempt, expires, now):
        raise ValueError("lease_lost")
    return artifact

from lease import can_publish

def test_old_token():
    assert not can_publish("new", "old", 100, 1)

def test_expired():
    assert not can_publish("same", "same", 1, 2)

